-- Registros demostrativos. La aplicación agrega las ocho recetas originales
-- automáticamente desde DataSeeder cuando MySQL no contiene esos slugs.
-- Estos INSERT se pueden ejecutar manualmente para verificar persistencia de usuarios.
USE mesaabierta;
ON DUPLICATE KEY UPDATE username=VALUES(username);
-- Verificación: SELECT id,username,display_name FROM app_user;
