INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('pasta-pesto','Pasta al pesto de albahaca','Italiana','Italia','Fácil',25,2,'Albahaca fresca, parmesano y un toque de limón para una pasta inolvidable.','Una receta simple que celebra los ingredientes frescos. La clave está en preparar el pesto en frío y mezclarlo con la pasta recién cocida.','https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=1300&q=85','Plato de pasta con salsa y hojas verdes','200 g de pasta larga\n1 taza de albahaca fresca\n30 g de queso parmesano\n25 g de nueces o piñones\n1 diente de ajo\n60 ml de aceite de oliva\nSal y pimienta\nRalladura de medio limón','Hierve abundante agua con sal y cocina la pasta hasta que esté al dente.\nTritura la albahaca, el ajo, las nueces, el parmesano y el aceite hasta obtener una salsa.\nReserva media taza del agua de cocción antes de escurrir la pasta.\nMezcla la pasta caliente con el pesto y agrega un poco del agua reservada para emulsionar.\nSirve con ralladura de limón, pimienta y un poco más de parmesano.','Vegetariana\nAlmuerzo\nPastas',98,TRUE,(SELECT id FROM app_user WHERE username='chefana'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('ramen-casero','Ramen casero reconfortante','Japonesa','Japón','Media',55,2,'Un caldo aromático, fideos suaves y vegetales llenos de sabor.','Una versión accesible del ramen: caldo con jengibre, ajo y soya, coronado con ingredientes frescos.','https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=1300&q=85','Tazón de ramen con fideos y guarniciones','300 g de fideos para ramen\n750 ml de caldo de pollo o verduras\n2 cucharadas de salsa de soya\n1 trozo de jengibre fresco\n2 dientes de ajo\n2 huevos\n100 g de champiñones\n1 cebollín\nAceite de sésamo','Hierve los huevos durante 7 minutos, enfría, pela y reserva.\nSofríe el ajo y el jengibre; añade el caldo y la salsa de soya.\nCocina los champiñones en el caldo a fuego suave durante 15 minutos.\nHierve los fideos por separado según sus instrucciones.\nDistribuye fideos y caldo en tazones; termina con huevo, cebollín y aceite de sésamo.','Caliente\nCena\nSopas',95,TRUE,(SELECT id FROM app_user WHERE username='chefleo'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('pizza-margarita','Pizza margarita artesanal','Italiana','Italia','Media',70,4,'Masa dorada, tomate, mozzarella y hojas frescas de albahaca.','La combinación clásica de Nápoles, con un horneado intenso para lograr bordes dorados y una base fina.','https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=1300&q=85','Pizza margarita con queso y albahaca','350 g de harina\n220 ml de agua tibia\n7 g de levadura seca\n1 cucharadita de sal\n200 g de salsa de tomate\n200 g de mozzarella\nHojas de albahaca\nAceite de oliva','Mezcla harina, levadura, agua y sal; amasa hasta conseguir una masa elástica.\nDeja reposar la masa 40 minutos en un recipiente cubierto.\nPrecalienta el horno a 250 °C con una bandeja en su interior.\nEstira la masa y añade una capa delgada de tomate y mozzarella.\nHornea entre 10 y 15 minutos; agrega albahaca y aceite de oliva al servir.','Horno\nPara compartir\nClásicos',100,FALSE,(SELECT id FROM app_user WHERE username='chefmia'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('ensalada-quinoa','Ensalada fresca de quinoa','Fusión','Perú','Fácil',30,2,'Una mezcla colorida de quinoa, palta, vegetales y cítricos.','Perfecta para un almuerzo ligero pero completo, con texturas crujientes y aliño vibrante.','https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=1300&q=85','Ensalada variada con hojas verdes y vegetales','1 taza de quinoa\n2 tazas de agua\n1 palta\n1 pepino\n10 tomates cherry\n1 zanahoria\nJugo de 1 limón\n2 cucharadas de aceite de oliva\nSal y cilantro','Lava la quinoa bajo agua fría para retirar su sabor amargo.\nCocínala en dos tazas de agua durante 15 minutos y deja enfriar.\nCorta la palta, el pepino, los tomates y la zanahoria.\nMezcla todos los ingredientes en una fuente amplia.\nAliña con limón, aceite de oliva, sal y cilantro antes de servir.','Vegetariana\nSaludable\nSin gluten',84,TRUE,(SELECT id FROM app_user WHERE username='chefana'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('tacos-pollo','Tacos de pollo y lima','Mexicana','México','Fácil',35,4,'Pollo especiado, tortillas calientes y salsa cremosa con lima.','Un plato perfecto para compartir: cada comensal prepara sus tacos a su manera.','https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?auto=format&fit=crop&w=1300&q=85','Tacos mexicanos rellenos con ingredientes frescos','400 g de pechuga de pollo\n8 tortillas pequeñas\n1 cucharadita de comino\n1 cucharadita de pimentón\n1 palta\n1 tomate\n1 cebolla morada\n2 limas\nYogur natural y cilantro','Corta el pollo en tiras y sazónalo con comino, pimentón y sal.\nDora el pollo en sartén durante 8 a 10 minutos hasta que esté completamente cocido.\nPica los vegetales y mezcla el yogur con el jugo de una lima.\nCalienta las tortillas en una sartén sin aceite.\nArma los tacos con pollo, verduras, salsa y cilantro.','Para compartir\nRápida\nCena',92,TRUE,(SELECT id FROM app_user WHERE username='chefleo'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('risotto-hongos','Risotto cremoso de hongos','Italiana','Italia','Media',45,3,'Arroz cremoso, champiñones dorados y un final de parmesano.','El secreto está en añadir el caldo poco a poco y remover hasta conseguir una textura suave.','https://images.unsplash.com/photo-1476124369491-e7addf5db371?auto=format&fit=crop&w=1300&q=85','Arroz cremoso servido con setas','250 g de arroz arborio\n250 g de champiñones\n1 litro de caldo de verduras\n1 cebolla pequeña\n50 g de queso parmesano\n30 g de mantequilla\nAceite de oliva\nSal, pimienta y tomillo','Calienta el caldo y mantenlo a fuego bajo.\nSaltea los champiñones en aceite hasta dorarlos y retíralos.\nSofríe la cebolla, incorpora el arroz y remueve durante dos minutos.\nAñade el caldo caliente de a cucharones, removiendo y esperando a que se absorba antes de agregar más.\nCuando el arroz esté cremoso, mezcla con champiñones, mantequilla, parmesano y tomillo.','Vegetariana\nReconfortante\nAlmuerzo',88,FALSE,(SELECT id FROM app_user WHERE username='chefmia'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('shakshuka','Shakshuka con tomates','Mediterránea','Túnez','Fácil',35,3,'Huevos cocinados sobre una salsa especiada de tomate y pimentón.','Ideal para brunch o cena: sirve con pan tostado para aprovechar toda la salsa.','https://images.unsplash.com/photo-1590412200988-a436970781fa?auto=format&fit=crop&w=1300&q=85','Preparación de huevos con tomate en sartén','4 huevos\n400 g de tomate triturado\n1 pimentón rojo\n1 cebolla\n2 dientes de ajo\n1 cucharadita de comino\n1 cucharadita de pimentón dulce\nAceite de oliva\nPerejil y pan','Sofríe la cebolla, el ajo y el pimentón picados.\nAgrega el tomate, el comino y el pimentón dulce; cocina 12 minutos.\nForma cuatro huecos en la salsa y casca un huevo en cada uno.\nTapa la sartén y cocina hasta que las claras estén firmes.\nTermina con perejil y sirve inmediatamente con pan.','Brunch\nVegetariana\nSartén',81,FALSE,(SELECT id FROM app_user WHERE username='chefana'),NOW(6));
INSERT IGNORE INTO receta(slug,nombre,cocina,pais,dificultad,minutos,porciones,resumen,introduccion,imagen,foto_alt,ingredientes_txt,pasos_txt,etiquetas_txt,popularidad,reciente,owner_id,created_at) VALUES ('brownies-chocolate','Brownies de chocolate intenso','Americana','Estados Unidos','Fácil',40,9,'Exterior delicado, centro húmedo y el sabor profundo del chocolate.','Un clásico de repostería que funciona perfecto con helado o una taza de café.','https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=1300&q=85','Brownies cuadrados de chocolate','180 g de chocolate amargo\n120 g de mantequilla\n150 g de azúcar\n3 huevos\n90 g de harina\n20 g de cacao amargo\n1 pizca de sal\n1 cucharadita de vainilla','Precalienta el horno a 175 °C y forra un molde cuadrado con papel mantequilla.\nDerrite el chocolate con la mantequilla a baño María y deja templar.\nBate huevos con azúcar y vainilla; incorpora el chocolate derretido.\nAgrega harina, cacao y sal con movimientos envolventes.\nHornea 22 a 27 minutos y deja enfriar antes de cortar en cuadrados.','Postres\nChocolate\nHorno',97,TRUE,(SELECT id FROM app_user WHERE username='chefleo'),NOW(6));
